/// <summary>
/// PricingAttribute of table <c>InventDim</c> field InventDimension7.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventDimension7 extends GUPPricingAttributeInventDim implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventDimension7);
}

    public Set getAllowedValues()
    {
        var       ret = new Set(Types::String);
        InventDim inventDim;

        while select inventDim
            group by InventDimension7
        {
            if (! ret.in(inventDim.InventDimension7))
            {
                ret.add(inventDim.InventDimension7);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventDim, InventDimension7));
        qbr.value(queryValue(_value));
    }
